import 'package:flutter/material.dart';class AppTheme {  AppTheme._(); // Developer Dark Theme Palette  static const Color bgPrimary = Color(0xFF191616); // True Black for OLED  static const Color bgSecondary = Color(0xFF322B28);  static const Color bgSidebar = Color(0xFF2D282A);  static const Color bgCodeMessageBubble = Color(0xFF231E1E);  static const Color bgCodeOrchOutput = Color(0xFF222023);  static const Color border = Color(0xFF464646);  static const Color textPrimary = Color(0xFFE1E1E1);  static const Color textSecondary = Color(0xFFB0B0B0);  static const Color textMuted = Color(0xFF7A7070);  static const Color accent = Color(0xFFB99B91); // warm amber / primary accent  static const Color accentMarrone = Color(0xFFAF8C82); // muted bronze  static const Color accentDarkMarrone = Color(0xFF8C695A); // dark bronze  static const Color codeDarkBlue = Color(0xFF32373C);  static const Color userBubble = Color(0xE64A4444);  static const Color aiBubble = Color(0xE62D2828);  static const Color codeBg = Color(0xFF000000);  static const Color codeText = Color(0xFFD4D4D4); // Status Colors  static const Color danger = Color(0xFFE14646);  static const Color success = Color(0xFF8DA399);  static const Color warning = Color(0xFFE9C46A);  static ThemeData darkTheme() {    const baseFont = "SystemFont";    return ThemeData(      useMaterial3: true,      brightness: Brightness.dark,      scaffoldBackgroundColor: bgPrimary,      fontFamily: baseFont,      colorScheme: const ColorScheme.dark(        primary: accent,        onPrimary: Colors.black,        secondary: textSecondary,        onSecondary: Colors.black,        surface: bgSecondary,        onSurface: textPrimary,        error: danger,        onError: Colors.white,        tertiary: success,      ),      textTheme: const TextTheme(        bodyLarge: TextStyle(color: textPrimary, fontSize: 15, height: 1.5),        bodyMedium: TextStyle(color: textPrimary, fontSize: 14, height: 1.5),        bodySmall: TextStyle(color: textSecondary, fontSize: 13, height: 1.4),        titleLarge: TextStyle(color: textPrimary, fontSize: 18, fontWeight: FontWeight.w600),        titleMedium: TextStyle(color: textPrimary, fontSize: 15, fontWeight: FontWeight.w600),        titleSmall: TextStyle(color: textSecondary, fontSize: 13, fontWeight: FontWeight.w500),        labelLarge: TextStyle(color: textPrimary, fontSize: 14, fontWeight: FontWeight.w500),      ),      dividerColor: border,      iconTheme: const IconThemeData(color: textSecondary, size: 20),      inputDecorationTheme: InputDecorationTheme(        filled: true,        fillColor: bgCodeOrchOutput,        contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),        border: OutlineInputBorder(          borderRadius: BorderRadius.circular(10),          borderSide: const BorderSide(color: border),        ),        enabledBorder: OutlineInputBorder(          borderRadius: BorderRadius.circular(10),          borderSide: const BorderSide(color: border),        ),        focusedBorder: OutlineInputBorder(          borderRadius: BorderRadius.circular(10),          borderSide: const BorderSide(color: accent),        ),        hintStyle: const TextStyle(color: textMuted),      ),      elevatedButtonTheme: ElevatedButtonThemeData(        style: ElevatedButton.styleFrom(          backgroundColor: accent,          foregroundColor: Colors.black,          elevation: 0,          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),          textStyle: const TextStyle(fontSize: 14, fontWeight: FontWeight.w500),        ),      ),      outlinedButtonTheme: OutlinedButtonThemeData(        style: OutlinedButton.styleFrom(          foregroundColor: textPrimary,          side: const BorderSide(color: border),          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),          textStyle: const TextStyle(fontSize: 14, fontWeight: FontWeight.w500),        ),      ),      textButtonTheme: TextButtonThemeData(        style: TextButton.styleFrom(          foregroundColor: textPrimary,          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(6)),        ),      ),      dialogTheme: DialogThemeData(        backgroundColor: bgSecondary,        elevation: 2,        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),      ),      snackBarTheme: const SnackBarThemeData(        backgroundColor: bgSecondary,        contentTextStyle: TextStyle(color: textPrimary, fontSize: 14),        behavior: SnackBarBehavior.floating,      ),    );  }}